check "Home Manager installs Mise but leaves language runtimes to it" "grep -Fq 'pkgs.mise' home/.config/home-manager/modules/common.nix && ! grep -REn 'pkgs\\.(go(_[[:alnum:]_]*)?|rust[[:alnum:]_]*|cargo|nodejs(_[[:alnum:]_]*)?|python3(_[[:alnum:]_]*)?)([[:space:];)]|$)' home/.config/home-manager"
check "Mise manages the global polyglot toolchain" "grep -Eq '^node[[:space:]]*=' home/.config/mise/config.toml && grep -Eq '^python[[:space:]]*=' home/.config/mise/config.toml && grep -Eq '^go[[:space:]]*=' home/.config/mise/config.toml && grep -Eq '^rust[[:space:]]*=' home/.config/mise/config.toml"
check "interactive shells activate Mise" "grep -Fq 'mise activate bash' home/.bashrc && grep -Fq 'mise activate zsh' home/.zshrc && grep -Fq 'mise activate fish' home/fish/zz-mise.fish"
check "zsh exposes Go-installed CLI tools before activating Mise" "go_bin_line=\$(grep -n '\$HOME/go/bin' home/.zshrc | head -n 1 | cut -d: -f1); mise_line=\$(grep -n 'mise activate zsh' home/.zshrc | cut -d: -f1); [[ -n \"\$go_bin_line\" && -n \"\$mise_line\" && \$go_bin_line -lt \$mise_line ]]"
check "Bash loads Go-installed CLI tools before activating Mise" "grep -Fq '\"\$HOME/go/bin\"' home/bash/.path && path_line=\$(grep -n '\$HOME/bash/.path' home/.bashrc | cut -d: -f1); mise_line=\$(grep -n 'mise activate bash' home/.bashrc | cut -d: -f1); [[ -n \"\$path_line\" && -n \"\$mise_line\" && \$path_line -lt \$mise_line ]]"
check "Fish activates Mise after legacy PATH modules" "[[ \"\$(printf '%s\\n' home/fish/*.fish | tail -n 1)\" == 'home/fish/zz-mise.fish' ]]"
check "installer provisions language toolchains through Mise" "grep -Fq 'ybw::packages::install_toolchains()' installer/packages.sh && grep -Fq 'mise install' installer/packages.sh && ! grep -Eq '^ybw::packages::install_official_(go|node|rust|toolchains)\\(\\)' installer/packages.sh"
check "installer keeps Mise toolchains scoped to macOS" "block=\$(sed -n '/^ybw::packages::install_toolchains()/,/^}/p' installer/packages.sh); grep -Fq 'if ! ybw::platform::is_macos; then' <<< \"\$block\""
check "installer activates Home Manager before Mise toolchains and npx tools" "block=\$(sed -n '/^ybw::packages::install_selected()/,/^}/p' installer/packages.sh); home_manager_line=\$(grep -n 'ybw::packages::activate_home_manager' <<< \"\$block\" | cut -d: -f1); mise_line=\$(grep -n 'ybw::packages::install_toolchains' <<< \"\$block\" | cut -d: -f1); npx_line=\$(grep -n 'ybw::packages::install_npx' <<< \"\$block\" | cut -d: -f1); [[ -n \"\$home_manager_line\" && -n \"\$mise_line\" && -n \"\$npx_line\" && \$home_manager_line -lt \$mise_line && \$mise_line -lt \$npx_line ]]"
check "npx tools execute inside the Mise environment" "block=\$(sed -n '/^ybw::packages::install_npx()/,/^}/p' installer/packages.sh); grep -Fq 'mise exec -- npx' <<< \"\$block\" && ! grep -Fq '/usr/bin/env npx' <<< \"\$block\" && ! grep -Fq 'ybw::command::exists npx' <<< \"\$block\""
check "legacy language version managers are disabled" "! grep -Fqx '    \"nvm\"' installer/packages.sh && ! grep -REn '/usr/local/go/bin|\$HOME/(node|python)/bin|~/((node|python)/bin)' home/bash/.path home/fish/path.fish"
check "Darwin Home Manager provides Fish without changing Linux login-shell ownership" "grep -Fq 'pkgs.fish' home/.config/home-manager/apps/darwin-cli.nix && grep -Fq '../../apps/darwin-cli.nix' home/.config/home-manager/modules/platform/darwin.nix && ! grep -REn 'programs\\.fish|pkgs\\.fish' home/.config/home-manager/modules/common.nix home/.config/home-manager/modules/platform/linux.nix"
check "Homebrew is no longer used for formula packages" "! grep -Eq 'brew (install|list) --formula|brew install --build-from-source|YBW_BREW_(FISH|CLI)_PACKAGES' installer/platform.sh"
check "retired macOS utilities remain removed" "! test -e home/.config/home-manager/apps/proxychains.nix && ! test -e home/fish/proxychains4.fish && ! grep -Eq 'pname = \"brightness\"|pkgs\\.(monitorcontrol|proxychains-ng)' home/.config/home-manager/apps/darwin-cli.nix home/.config/home-manager/home.nix && grep -Fq 'pname = \"im-select\"' home/.config/home-manager/apps/darwin-cli.nix"
check "Home Manager provides the complete Fish runtime" "for package in eza fd fzf mcfly peco starship zoxide; do grep -Fq \"pkgs.\$package\" home/.config/home-manager/modules/common.nix || exit 1; done"
check "Home Manager installs delta through Git integration" "grep -Fq 'programs.delta.enable = true;' home/.config/home-manager/apps/git.nix && grep -Fq 'programs.delta.enableGitIntegration = true;' home/.config/home-manager/apps/git.nix && ! grep -Fq 'pkgs.delta' home/.config/home-manager/modules/common.nix"
check "Home Manager replaces removed silver-searcher with ripgrep" "grep -Fq 'pkgs.ripgrep' home/.config/home-manager/modules/common.nix && ! grep -Rq 'pkgs.silver-searcher' home/.config/home-manager"
check "Home Manager installs Jujutsu instead of tidwall jj" "grep -Fq 'pkgs.jujutsu' home/.config/home-manager/modules/common.nix && ! grep -Eq '^[[:space:]]*pkgs\.jj[[:space:]]*$' home/.config/home-manager/modules/common.nix"
check "Home Manager flake exposes supported platform targets" "test -f home/.config/home-manager/flake.lock && for target in macos-aarch64 macos-x86_64 linux-aarch64 linux-x86_64 wsl-aarch64 wsl-x86_64; do grep -Fq \"\$target\" home/.config/home-manager/flake.nix || exit 1; done"
check "Home Manager separates platform and role modules" "test -f home/.config/home-manager/modules/platform/darwin.nix && test -f home/.config/home-manager/modules/platform/linux.nix && test -f home/.config/home-manager/modules/platform/wsl.nix && test -f home/.config/home-manager/modules/role/development.nix && test -f home/.config/home-manager/modules/role/desktop.nix"
check "headless Linux profiles disable generic GPU integration" "grep -Fq 'targets.genericLinux.gpu.enable = false;' home/.config/home-manager/modules/platform/linux.nix"
check "Linux activation rejects generation-bound login shells" "grep -Fq 'home.activation.checkStableLoginShell' home/.config/home-manager/modules/platform/linux.nix && grep -Fq 'entryBefore [ \"writeBoundary\" ]' home/.config/home-manager/modules/platform/linux.nix && grep -Fq '\$HOME/.nix-profile/' home/.config/home-manager/modules/platform/linux.nix && grep -Fq '\$HOME/.local/state/nix/profiles/' home/.config/home-manager/modules/platform/linux.nix && grep -Fq '/nix/var/nix/profiles/' home/.config/home-manager/modules/platform/linux.nix && grep -Fq '/nix/store/' home/.config/home-manager/modules/platform/linux.nix"
check "desktop profile preserves configured developer fonts" "grep -Fq 'pkgs.jetbrains-mono' home/.config/home-manager/modules/role/desktop.nix && grep -Fq 'pkgs.fira-code' home/.config/home-manager/modules/role/desktop.nix"
check "standard macOS install resolves Fish independently of Homebrew" "grep -Fq 'ybw::macos::find_fish()' installer/platform.sh && sed -n '/^ybw::packages::install_selected()/,/^}/p' installer/packages.sh | grep -Fq 'fish_path=\"\$(ybw::macos::find_fish)\"'"
check "standard Linux install provisions the Fish executable" "sed -n '/^ybw::packages::install_selected()/,/^}/p' installer/packages.sh | grep -Fq 'if ! ybw::linux::install_fish; then'"
check "Linux Fish installation supports common package managers" "for manager in apt-get dnf yum pacman zypper apk; do grep -Fq \"ybw::command::exists \$manager\" installer/platform.sh || exit 1; done"
check "Arch Fish installation avoids a partial system upgrade" "grep -Fq 'ybw::command::as_root pacman -S --needed --noconfirm fish' installer/platform.sh && ! grep -Fq 'pacman -Sy' installer/platform.sh"
check "Homebrew is required only for remaining macOS casks" "block=\$(sed -n '/if \[\[ \"\$platform\" == \"macOS\" \]\]; then/,/^    elif/p' installer/plan.sh); grep -Fq 'if [[ \"\$YBW_INSTALL_PLAN_MAC_APPS\" == true ]]' <<< \"\$block\" && grep -Fq 'ybw::command::require brew' <<< \"\$block\""
check "installer selects Home Manager Fish as the preferred macOS login shell" "grep -Fq '\$HOME/.local/state/nix/profiles/home-manager/home-path/bin/fish' installer/platform.sh && grep -Fq 'sudo chsh -s \"\$fish_path\" \"\$USER\"' installer/platform.sh && ! grep -Fq 'brew --prefix' installer/platform.sh"
check "installer selects Linux Fish as login shell" "grep -Fq 'fish_path=\"\$(ybw::linux::find_fish)\"' installer/packages.sh && grep -Fq 'ybw::linux::configure_fish_login_shell \"\$fish_path\"' installer/packages.sh && ! grep -Fq 'configure_fish_login_shell \"\$(command -v fish)\"' installer/platform.sh"
check "Linux login shell rejects generation-bound Fish paths" "grep -Fq '\$HOME/.nix-profile/' installer/core.sh && grep -Fq '\$HOME/.local/state/nix/profiles/' installer/core.sh && grep -Fq '/nix/store/' installer/core.sh"
check "native Fish config loads repository modules" "grep -Fq 'for file in ~/fish/*.fish' home/.config/fish/config.fish"
check "native Fish config loads the Home Manager profile" "grep -Fq '~/.nix-profile/bin' home/fish/path.fish"
check "Fish exposes npm-global executables" "grep -Fq '~/.npm-global/bin' home/fish/path.fish"
check "installer activates the locked Home Manager flake" "grep -Fq 'nix run \"\$home_manager_dir#home-manager\"' installer/packages.sh && grep -Fq -- '--flake \"\$home_manager_dir#\$target\" switch' installer/packages.sh"
check "Home Manager activation is verbose and memory bounded" "grep -Fq -- '--impure -v --option max-jobs 1 --option cores 2' installer/packages.sh"
check "Home Manager activation rejects a non-symlink Nix profile" "setup_body=\$(sed -n '/^ybw::packages::activate_home_manager()/,/^}/p' installer/packages.sh); grep -Fq '[[ -e \"\$HOME/.nix-profile\" && ! -L \"\$HOME/.nix-profile\" ]]' <<< \"\$setup_body\" && grep -Fq '~/.nix-profile must be a symlink' <<< \"\$setup_body\""
check "Oh My Fish installer supports headless setup" "setup_body=\$(sed -n '/^ybw::postinstall::setup_oh_my_fish()/,/^}/p' installer/postinstall.sh); grep -Fq -- '--noninteractive --yes' <<< \"\$setup_body\" && grep -Fq 'if ! ybw::postinstall::setup_oh_my_fish; then' installer/postinstall.sh"
check "Home Manager activation is explicit" "package_phase=\$(sed -n '/^ybw::packages::install_selected()/,/^}/p' installer/packages.sh); grep -Fq 'if [[ \"\$YBW_INSTALL_PLAN_HOME_MANAGER\" == true ]]' <<< \"\$package_phase\" && grep -Fq 'ybw::packages::activate_home_manager \"\$YBW_INSTALL_PLAN_HOME_MANAGER_PROFILE\"' <<< \"\$package_phase\""
check "installer defaults to skipping Home Manager activation" "bash -c 'source ./bootstrap.sh; ybw::plan::reset; [[ \"\$YBW_INSTALL_PLAN_HOME_MANAGER\" == false && \"\$YBW_INSTALL_PLAN_HOME_MANAGER_PROFILE\" == development ]]'"
check "legacy Home Manager channels are no longer used" "! grep -rEq --include='*.sh' --exclude='install-nix.sh' 'nix-channel|nix-shell.*home-manager' installer"
check "Nix prefers the TUNA binary cache with official fallback" "grep -Fq 'substituters = https://mirrors.tuna.tsinghua.edu.cn/nix-channels/store https://cache.nixos.org/' home/.config/nix/nix.conf && ! grep -Eq 'mirror.sjtu|mirrors.ustc' home/.config/nix/nix.conf"
check "Nix trusts the official cache signing key" "grep -Fq 'trusted-public-keys = cache.nixos.org-1:6NCHdD59X431o0gWypbMrAURkbJ16ZPMQFGspcDShjY=' home/.config/nix/nix.conf && ! grep -Fq 'kb9Kaaa' home/.config/nix/nix.conf"
check "Fish startup does not write macOS defaults" "! grep -REn '^[[:space:]]*defaults[[:space:]]+write' home/fish"
check "Fish startup does not mutate universal variables" "! grep -REn 'set[[:space:]]+(-[^[:space:]]*U|--universal)' home/fish"
check "installer owns Dock defaults" "grep -Fq 'defaults write com.apple.dock autohide -int 1' installer/platform.sh && grep -Fq 'defaults write com.apple.dock tilesize -int 44' installer/platform.sh"
check "installer disables automatic macOS updates" "grep -Fq 'sudo defaults write /Library/Preferences/com.apple.SoftwareUpdate AutomaticCheckEnabled -bool false' installer/platform.sh && grep -Fq 'sudo defaults write /Library/Preferences/com.apple.SoftwareUpdate AutomaticDownload -bool false' installer/platform.sh && grep -Fq 'sudo defaults write /Library/Preferences/com.apple.SoftwareUpdate AutomaticallyInstallMacOSUpdates -bool false' installer/platform.sh"
